// Skyworks patch v1 - white quartz crystals for the floating quartz geodes ("quartz meteors").
//
// Same look/behaviour as the amethyst buds and cluster, but white. Like amethyst, a cluster mined with a pickaxe drops
// minecraft:quartz (4, fortune applies), buds drop nothing without silk touch.
// Blocks need a 6-way "facing" property because minecraft:geode places its inner crystals with it.
// Models/textures/blockstates live in kubejs/assets/kubejs (generated by tools/gen_quartz_assets.py);
// loot tables in server_scripts/skyworks/quartz.js (generateData, overrides the auto-generated "drops itself" tables).

StartupEvents.registry('block', event => {
  const FACING = Java.loadClass('net.minecraft.world.level.block.state.properties.BlockStateProperties').FACING
  const SoundType = Java.loadClass('net.minecraft.world.level.block.SoundType')
  const crystal = (id, name, light) => {
    event.create(id)
      .displayName(name)
      .property(FACING)
      .waterlogged()
      .defaultState(s => s.set(FACING, 'up'))
      .placementState(s => s.set(FACING, s.clickedFace.getName()).waterlogged(s.isInWater()))
      .soundType(SoundType.AMETHYST_CLUSTER)
      .hardness(1.5)
      .resistance(1.5)
      .lightLevel(light)
      .renderType('cutout')
      .noCollision()
      .box(4, 4, 4, 12, 12, 12)
      .tagBlock('minecraft:mineable/pickaxe')
  }
  crystal('quartz_cluster', 'Quartz Cluster', 5 / 15)
  crystal('quartz_bud_large', 'Large Quartz Bud', 4 / 15)
  crystal('quartz_bud_medium', 'Medium Quartz Bud', 2 / 15)
  crystal('quartz_bud_small', 'Small Quartz Bud', 1 / 15)
})
